SELECT pp.id, pp.symbol, pp.entry_price, pp.stop_loss, pp.take_profit, pp.closed_at, MAX(e.price) AS max_30m_after, MIN(e.price) AS min_30m_after, (MAX(e.price) >= pp.entry_price) AS recovered_to_entry, (MAX(e.price) >= pp.take_profit) AS reached_tp_after, COUNT(e.id) AS n_events FROM crypto_ai.paper_position pp LEFT JOIN crypto_ai.market_price_event e ON e.symbol = pp.symbol AND e.observed_at > pp.closed_at AND e.observed_at <= pp.closed_at + INTERVAL 30 MINUTE WHERE pp.status = 'STOPPED' GROUP BY pp.id, pp.symbol, pp.entry_price, pp.stop_loss, pp.take_profit, pp.closed_at ORDER BY pp.id LIMIT 80